import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';

const Login = () => {
  const [form, setForm] = useState({ email: '', password: '' });
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  // Function to generate a random email (same logic as register)
  const getRandomEmail = () => {
    const randomString = Math.random().toString(36).substring(2, 10); // generates a random string
    return `${randomString}@example.com`;
  };

  // Function to generate a random password (same logic as register)
  const getRandomPassword = () => {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()";
    let password = "";
    for (let i = 0; i < 8; i++) {
      password += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return password;
  };

  // Set random values on initial render for testing purposes
  useEffect(() => {
    const randomEmail = getRandomEmail();
    const randomPassword = getRandomPassword();

    setForm({
      email: randomEmail,
      password: randomPassword,
    });
  }, []); // Empty dependency array ensures this runs only once when the component mounts

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post('/auth/login', form);
      setMessage(res.data.message || 'Login successful');
      localStorage.setItem('token', res.data.token); // Store token in localStorage
      navigate(`/home/${res.data.userId}`); // Redirect to home page with user ID
    } catch (err) {
      setMessage(err.response?.data?.message || 'Login failed');
    }
  };

  return (
    <div>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <input
          name="email"
          type="email"
          placeholder="Email"
          value={form.email}
          onChange={(e) => setForm({ ...form, email: e.target.value })}
          required
        />
        <input
          name="password"
          type="password"
          placeholder="Password"
          value={form.password}
          onChange={(e) => setForm({ ...form, password: e.target.value })}
          required
        />
        <button type="submit">Login</button>
      </form>
      {message && <p>{message}</p>}
    </div>
  );
};

export default Login;
